const $=id=>document.getElementById(id),{minutes,netMinutes,validate}=Attendance;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const currentTime=()=>new Date().toTimeString().slice(0,5),key='iswagty-demo-v1';
const seedDate='2026-09-24',departments=['IT bölümi','Hasapçylyk','Işgärler bölümi','Satuw bölümi'];
function seed(){return {version:1,employees:[['Myrat Amanow',0],['Aýna Orazowa',1],['Serdar Myradow',0],['Maýa Annagulyýewa',2],['Döwlet Gurbanow',3],['Oguljan Berdiýewa',1],['Arslan Ataýew',3],['Leýli Hojamyradowa',0]].map(([name,dept],i)=>({id:i+1,name,department:departments[dept]})),days:{[seedDate]:{'1':{type:'present',entry:'07:55',exit:'17:00'},'2':{type:'present',entry:'08:00',exit:'17:00'},'3':{type:'present',entry:'08:17',exit:'17:00'},'4':{type:'present',entry:'07:58',exit:'17:00'},'5':{type:'present',entry:'08:05',exit:'15:00'},'6':{type:'leave',entry:'',exit:''},'7':{type:'absent',entry:'',exit:''},'8':{type:'present',entry:'08:00',exit:'17:00'}}}};}
let state=seed(),selectedDate=seedDate,view='overview';
try{const saved=localStorage.getItem(key);if(saved){const parsed=JSON.parse(saved);if(parsed.version!==1||!Array.isArray(parsed.employees)||!parsed.days||!parsed.employees.every(e=>Number.isInteger(e.id)&&typeof e.name==='string'&&departments.includes(e.department)))throw Error();state=parsed;}}catch{$('storageWarning').hidden=false;$('storageWarning').textContent='Saklanan maglumatlary okap bolmady. Nusga maglumatlar görkezilýär.';}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));return true;}catch{$('storageWarning').hidden=false;$('storageWarning').textContent='Brauzere ýazyp bolmady. Üýtgeşmeler diňe şu açyk sahypada saklanýar; CSV hasabaty ýükläp alyň.';return false;}}
const getRecord=id=>state.days[selectedDate]?.[id]||{type:'unrecorded',entry:'',exit:''};
const labels={working:'Işde',late:'Giç gelen',done:'Tamamlan',leave:'Rugsatda',absent:'Gelmedik',unrecorded:'Bellik ýok',incomplete:'Çykyş ýok'};
function status(r){return r.type!=='present'?r.type:r.exit?'done':selectedDate===localDate()?(minutes(r.entry)>480?'late':'working'):'incomplete';}
function duration(r){if(r.type!=='present')return 0;if(r.exit)return netMinutes(r.entry,r.exit);return selectedDate===localDate()?netMinutes(r.entry,currentTime()):null;}
const format=m=>m===null?'Çykyş ýok':`${Math.floor(m/60)} sag ${m%60} min`;
const initial=e=>e.name.split(/\s+/).map(n=>n[0]).slice(0,2).join('');
const employeeCell=e=>`<div class="employee-cell"><i class="initials a${e.id%4}">${esc(initial(e))}</i><div><b>${esc(e.name)}</b><small>IG-${String(e.id).padStart(3,'0')}</small></div></div>`;
const prettyDate=d=>new Date(d+'T12:00:00').toLocaleDateString('tk-TM',{day:'numeric',month:'long',year:'numeric'});
function filtered(){const q=$('search').value.trim().toLocaleLowerCase();return state.employees.filter(e=>{const r=getRecord(e.id),s=$('status').value;return (!q||`${e.name} IG-${String(e.id).padStart(3,'0')}`.toLocaleLowerCase().includes(q))&&(!$('department').value||e.department===$('department').value)&&(!s||(s==='late'?r.type==='present'&&minutes(r.entry)>480:s==='working'?r.type==='present'&&!r.exit&&selectedDate===localDate():status(r)===s));});}
function renderRows(){const list=filtered();$('attendanceRows').innerHTML=list.map(e=>{const r=getRecord(e.id);return `<tr><td>${employeeCell(e)}</td><td>${esc(e.department)}</td><td class="time">${esc(r.entry||'—')}</td><td class="time">${esc(r.exit||'—')}</td><td>${r.type==='present'?format(duration(r)):'—'}</td><td><span class="pill ${status(r)}">${labels[status(r)]||'Bellik ýok'}</span></td><td><button class="edit" data-record="${e.id}" aria-label="${esc(e.name)} wagt belligini üýtgetmek">✎</button></td></tr>`;}).join('')||'<tr><td colspan="7" class="empty">Işgär tapylmady. Gözlegi ýa-da süzgüçleri üýtgediň.</td></tr>';$('resultCount').textContent=`${state.employees.length} işgärden ${list.length} sanysy görkezilýär`;}
function metric(label,value,icon){return `<article><i>${icon}</i><div><small>${label}</small><strong>${value}</strong></div></article>`;}
function render(){const records=state.employees.map(e=>getRecord(e.id)),n=records.length,p=records.filter(r=>r.type==='present').length,l=records.filter(r=>r.type==='leave').length,a=records.filter(r=>r.type==='absent').length,u=n-p-l-a,total=records.reduce((sum,r)=>sum+(duration(r)||0),0),late=records.filter(r=>r.type==='present'&&minutes(r.entry)>480).length,done=records.filter(r=>r.type==='present'&&r.exit).length,working=records.filter(r=>r.type==='present'&&!r.exit&&selectedDate===localDate()).length;
$('dayLabel').textContent=prettyDate(selectedDate)+(selectedDate===seedDate?' · Nusga maglumatlar':'');$('clock').textContent=selectedDate===localDate()?currentTime():'08:00–17:00';$('clock').classList.toggle('historical',selectedDate!==localDate());$('clockCaption').textContent=selectedDate===localDate()?'Şu gün · Häzirki wagt':prettyDate(selectedDate);$('dayProgress').style.width=selectedDate<localDate()?'100%':`${Math.max(0,Math.min(100,(minutes(currentTime())-480)/540*100))}%`;
$('percentage').textContent=`${n?Math.round(p/n*100):0}%`;$('ring').style.background=`conic-gradient(#cdeb83 0 ${p/n*100||0}%,#b6a4db ${p/n*100||0}% ${(p+l)/n*100||0}%,#e3a5a1 ${(p+l)/n*100||0}% ${(p+l+a)/n*100||0}%,#e9edf2 0)`;$('employeeCount').textContent=n+' işgär';$('legend').innerHTML=[['Işe gelen',p,'#cdeb83'],['Rugsatda',l,'#b6a4db'],['Gelmedik',a,'#e3a5a1'],['Bellik ýok',u,'#e9edf2']].map(([label,count,color])=>`<div><span><i style="background:${color}"></i>${label}</span><b>${count}</b></div>`).join('');$('stats').innerHTML=metric('Häzir işde',working,'↗')+metric('Giç gelen',late,'◷')+metric('Işini tamamlan',done,'↘')+metric('Jemi iş wagty',format(total),'∑');renderRows();
$('employeeGrid').innerHTML=state.employees.map(e=>`<article class="employee-card"><div class="employee-card-top"><i class="initials a${e.id%4}">${esc(initial(e))}</i><small>IG-${String(e.id).padStart(3,'0')}</small></div><h3>${esc(e.name)}</h3><p>${esc(e.department)}</p><div class="actions"><button data-record="${e.id}">Wagt belligi</button><button data-employee="${e.id}">Üýtgetmek</button></div></article>`).join('');$('reportDate').textContent=prettyDate(selectedDate);$('reportStats').innerHTML=metric('Jemi arassa iş wagty',format(total),'∑')+metric('Işe gelen işgärler',`${p} / ${n}`,'↗')+metric('Jemi gijikme',records.reduce((s,r)=>s+(r.type==='present'?Math.max(0,minutes(r.entry)-480):0),0)+' min','◷')+metric('Çykyşy bellenmedik',records.filter(r=>r.type==='present'&&!r.exit).length,'!');$('reportRows').innerHTML=state.employees.map(e=>{const r=getRecord(e.id);return `<tr><td>${esc(e.name)}</td><td>${esc(r.entry||'—')}</td><td>${esc(r.exit||'—')}</td><td>${r.type==='present'?format(duration(r)):labels[status(r)]}</td><td>${r.type==='present'?Math.max(0,minutes(r.entry)-480)+' min':'—'}</td></tr>`;}).join('');}
function setView(next){view=['overview','attendance','employees','reports'].includes(next)?next:'overview';const titles={overview:['Wagtyň takyk hasaby','Girişden çykyşa çenli — ähli iş wagty bir ýerde.','Umumy syn'],attendance:['Giriş we çykyş','Gündelik wagt belliklerini dolandyryň.','Giriş we çykyş'],employees:['Işgärler','Toparyň işgärleri we bölümleri.','Işgärler'],reports:['Günlük hasabat','Iş wagtynyň we gijikmeleriň aýdyň hasaby.','Hasabat']};$('pageTitle').innerHTML=titles[view][0]+'<span>.</span>';$('pageDescription').textContent=titles[view][1];$('breadcrumb').textContent=titles[view][2];$('overview').hidden=view!=='overview';$('attendancePanel').hidden=!['overview','attendance'].includes(view);$('employeesPanel').hidden=view!=='employees';$('reportsPanel').hidden=view!=='reports';document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});}
function toggleTime(){const present=$('recordType').value==='present';$('timeFields').hidden=!present;$('entry').required=present;$('entry').disabled=!present;$('exit').disabled=!present;}
function loadRecord(){const r=getRecord(Number($('recordEmployee').value));$('recordType').value=r.type==='unrecorded'?'present':r.type;$('entry').value=r.entry||'';$('exit').value=r.exit||'';$('recordError').textContent='';toggleTime();}
function openRecord(id=state.employees[0]?.id){if(!id)return;$('recordEmployee').innerHTML=state.employees.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('');$('recordEmployee').value=id;$('recordDate').textContent=prettyDate(selectedDate);loadRecord();$('recordDialog').showModal();}
let toastTimer;function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function openEmployee(id){const e=state.employees.find(e=>e.id===id);$('employeeForm').reset();$('employeeId').value=e?.id||'';$('employeeName').value=e?.name||'';$('employeeDepartment').value=e?.department||departments[0];$('employeeDialogTitle').textContent=e?'Işgäri üýtgetmek':'Täze işgär';$('employeeError').textContent='';$('employeeDialog').showModal();}
function exportCSV(list){const rows=[['Sene','Işgär','Bölüm','Giriş','Çykyş','Arassa iş wagty (min)','Gijikme (min)','Ýagdaý'],...list.map(e=>{const r=getRecord(e.id);return [selectedDate,e.name,e.department,r.entry,r.exit,r.type==='present'?(duration(r)??'Çykyş ýok'):'',r.type==='present'?Math.max(0,minutes(r.entry)-480):'',labels[status(r)]];})];const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(row=>row.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`iswagty-${selectedDate}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV hasabaty taýýar.');}
$('date').value=selectedDate;$('date').max=localDate();$('department').insertAdjacentHTML('beforeend',departments.map(d=>`<option>${d}</option>`).join(''));$('date').onchange=()=>{if(!$('date').value||$('date').value>localDate()){$('date').value=selectedDate;return;}selectedDate=$('date').value;render();};$('search').oninput=renderRows;$('department').onchange=renderRows;$('status').onchange=renderRows;
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.view){setView(b.dataset.view);history.replaceState(null,'','#'+view);}if(b.dataset.close)$(b.dataset.close).close();if(b.dataset.record)openRecord(Number(b.dataset.record));if(b.dataset.employee)openEmployee(Number(b.dataset.employee));});window.addEventListener('hashchange',()=>setView(location.hash.slice(1)));
$('recordButton').onclick=()=>openRecord();$('recordEmployee').onchange=loadRecord;$('recordType').onchange=toggleTime;$('addEmployee').onclick=()=>openEmployee();
$('recordForm').onsubmit=e=>{e.preventDefault();const type=$('recordType').value,r={type,entry:type==='present'?$('entry').value:'',exit:type==='present'?$('exit').value:''},error=validate(r,selectedDate,localDate(),minutes(currentTime()));if(error){$('recordError').textContent=error;return;}state.days[selectedDate]??={};state.days[selectedDate][Number($('recordEmployee').value)]=r;const saved=persist();$('recordDialog').close();render();toast(saved?'Wagt belligi saklandy.':'Bellik diňe şu sessiýada saklandy.');};
$('employeeForm').onsubmit=e=>{e.preventDefault();const name=$('employeeName').value.trim().replace(/\s+/g,' '),id=Number($('employeeId').value);if(!name){$('employeeError').textContent='Işgäriň adyny giriziň.';return;}const data={name,department:$('employeeDepartment').value};if(id)Object.assign(state.employees.find(e=>e.id===id),data);else state.employees.push({id:Math.max(0,...state.employees.map(e=>e.id))+1,...data});const saved=persist();$('employeeDialog').close();render();toast(saved?'Işgäriň maglumatlary saklandy.':'Maglumatlar diňe şu sessiýada saklandy.');};
$('exportAttendance').onclick=()=>exportCSV(filtered());$('exportReport').onclick=()=>exportCSV(state.employees);$('printReport').onclick=()=>window.print();render();setView(location.hash.slice(1));setInterval(()=>{if(selectedDate===localDate())render();$('date').max=localDate();},60000);
